  UNION ALL SELECT 'Reads and runs each line live as it goes' AS t, 0 AS c, 'Those describe an interpreter, a database or a stylesheet, not a compiler.' AS e, 1 AS s
  UNION ALL SELECT 'Stores data in tables' AS t, 0 AS c, 'Those describe an interpreter, a database or a stylesheet, not a compiler.' AS e, 2 AS s
  UNION ALL SELECT 'Makes the screen look attractive' AS t, 0 AS c, 'Those describe an interpreter, a database or a stylesheet, not a compiler.' AS e, 3 AS s) o WHERE @q > 0;
