  UNION ALL SELECT 'A security certificate' AS t, 0 AS c, 'It lives in the browser, not on the server, and is about page structure, not data or security.' AS e, 1 AS s
  UNION ALL SELECT 'The browser\'s live tree of the page\'s elements, which JavaScript can change' AS t, 1 AS c, 'The Document Object Model is built in the browser from the HTML.' AS e, 2 AS s
