  UNION ALL SELECT 'Fixing it later means reworking finished designs and code, whereas getting it right initially costs little extra' AS t, 1 AS c, 'Retro-fitting is slow and expensive; early habits are cheap and benefit everyone.' AS e, 2 AS s
