INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'A supplier says: "We deploy in containers on Kubernetes, with a CI/CD pipeline and weekly releases. Our code is reviewed in GitHub." Explain in plain English what each part means for the Repairs project, and one risk or question you would still raise.', 'Containers mean the software is packaged with everything it needs, so test and live behave the same and environments can be rebuilt reliably. Kubernetes means the supplier\'s platform automatically keeps the right number of copies running, replaces failed ones and can scale up for busy periods such as cold snaps, with updates rolled out gradually. A CI/CD pipeline means changes are built, tested and released through an automated, repeatable route rather than by hand, which reduces human error. Weekly releases suggest small, frequent changes, which are generally safer than rare large ones, provided there is a test environment for us to try releases and notice of what is changing. Code review in GitHub means a second person checks each change before it joins the main version, and there is a history of who changed what. Questions I would still raise: Do we get access to the repository or an escrow arrangement? Which environments are available for our UAT and how much notice of releases do we get? How is the rollback done and how quickly? How is monitoring and alerting handled, and what does the SLA say? Also, who has the skills to support this, since Kubernetes in particular needs specialist knowledge, and what happens to us if the supplier stops trading?', 0 FROM DUAL WHERE @mod > 0;

