INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'A confident statement that is false or invented' AS t, 1 AS c, 'Models generate plausible language and can state untrue things fluently.' AS e, 0 AS s
  UNION ALL SELECT 'A picture the model draws' AS t, 0 AS c, 'It refers to false content, not to images, speed or security.' AS e, 1 AS s
  UNION ALL SELECT 'A slow response' AS t, 0 AS c, 'It refers to false content, not to images, speed or security.' AS e, 2 AS s
  UNION ALL SELECT 'A security warning' AS t, 0 AS c, 'It refers to false content, not to images, speed or security.' AS e, 3 AS s) o WHERE @q > 0;
INSERT INTO pm_learning_quiz_questions (lesson_id, kind, format, prompt, sort_order)
SELECT @lesson, 'quick_check', 'multiple_choice', 'Which is the safest way to use AI for a work document?', 1 FROM DUAL WHERE @lesson > 0;
SET @q := IF(@lesson > 0, LAST_INSERT_ID(), 0);
INSERT INTO pm_learning_quiz_options (question_id, option_text, is_correct, explanation, sort_order)
SELECT @q, o.t, o.c, o.e, o.s FROM (SELECT 'Publish whatever it produces' AS t, 0 AS c, 'Unchecked output and unapproved sharing of personal data are the main risks.' AS e, 0 AS s
  UNION ALL SELECT 'Treat its output as a draft, check facts against reliable sources, and keep a person accountable' AS t, 1 AS c, 'A human in the loop who verifies the output keeps quality and accountability.' AS e, 1 AS s
  UNION ALL SELECT 'Paste in any personal data to get better results' AS t, 0 AS c, 'Unchecked output and unapproved sharing of personal data are the main risks.' AS e, 2 AS s
  UNION ALL SELECT 'Use it only when no one is watching' AS t, 0 AS c, 'Unchecked output and unapproved sharing of personal data are the main risks.' AS e, 3 AS s) o WHERE @q > 0;

INSERT INTO pm_learning_quiz_questions (module_id, kind, format, prompt, model_answer, sort_order)
SELECT @mod, 'scenario', 'reflection', 'Two weeks after launch, the Repairs service shows an occasional fault: some tenants are given an appointment slot that another tenant has also been given, and some contractors are paid twice for the same job. Nothing can be reproduced in testing. Explain what kinds of problem these are and what you would ask the supplier.', 'These are classic concurrency problems. The double-booked slots look like a race condition: two requests check availability at nearly the same time, both see a free slot, and both book it, because the check and the booking are not one atomic step. The double payments look like missing idempotency: a request that is retried after a timeout is processed twice. Because they only occur under real timing and retries, they cannot be reproduced when one tester works alone. Questions for the supplier: Is the booking done as a single atomic operation or inside a database transaction with locking or a unique constraint on the slot? Are payment and job-completion requests protected by idempotency keys so repeats are recognised? Is there version checking so that two updates to the same record cannot silently overwrite each other? Do they perform load and concurrency testing, with many users and repeated requests? What logging and monitoring exist to detect duplicates, and is there a regular reconciliation between completed jobs and payments, who investigates differences, and how are the duplicates already paid being recovered? I would also ask for an incident report that identifies the root cause and the fix, with a test that proves it will not recur.', 0 FROM DUAL WHERE @mod > 0;

-- ===== Glossary (existing terms are left untouched) =====
INSERT IGNORE INTO pm_learning_glossary (term, definition) VALUES
  ('compiler', 'A program that translates all of a program\'s source code into a ready-to-run file in one go, before it is run.'),
  ('interpreter', 'A program that reads source code and carries it out as it goes, line by line, without a separate translation step beforehand.'),
  ('DOM', 'Document Object Model: the tree of elements the browser builds from a page\'s HTML, which JavaScript can read and change to update what you see.'),
  ('object-oriented', 'A way of organising code around "objects" that bundle together information and the actions that can be done to it, such as a Repair that can be escalated or closed.'),
  ('functional programming', 'A way of organising code as small functions that take input and return output without changing anything else, chained together like machines on a line.'),
  ('framework', 'A ready-made structure for building a certain kind of software, such as React for web screens or Laravel for web back ends. It decides how your code is organised.'),
  ('library', 'A collection of ready-made code for one particular job, such as handling dates or drawing charts, which you call from your own code.'),
  ('CMS', 'Content Management System: software such as WordPress that lets non-developers create and edit a website\'s pages without writing code.'),
  ('React', 'A very widely used JavaScript library for building interactive screens out of reusable components.'),
  ('IDE', 'Integrated Development Environment: the editor developers write code in, with built-in help such as highlighting, auto-complete, debugging and testing.'),
  ('linting', 'Automatic checking of code for likely mistakes and style problems, a bit like a spell-checker for code.'),
  ('Prettier', 'A popular tool that automatically formats code in one consistent style, so nobody argues about spacing.'),
  ('Git', 'The standard version control system: it records every change to code as a labelled step that can be compared, shared and undone.'),
  ('GitHub', 'A website that hosts Git repositories and adds tools for teamwork such as pull requests, issues and code review.'),
  ('pull request', 'A proposal to merge changes from one branch into another, which a colleague reviews and approves before it joins the main version.'),
  ('code review', 'A colleague reading and checking proposed code changes for mistakes, security problems and clarity before they are accepted.'),
  ('DevOps', 'A way of working in which the people who build software and the people who run it work as one team, using automation to release changes quickly and safely.'),
  ('container', 'A lightweight, self-contained package holding an application and everything it needs to run, so it behaves the same wherever it is started.'),
  ('Docker', 'The best-known tool for building and running containers.'),
  ('Kubernetes', 'Software that runs and manages many containers across many servers, keeping the right number running and replacing any that fail.'),
  ('operating system', 'The core software of a device, such as Windows, macOS, Linux, iOS or Android, which manages the hardware and runs other programs.'),
  ('rendering engine', 'The part of a browser that turns code into the page you see. Chrome and Edge use Blink, Safari uses WebKit and Firefox uses Gecko.'),
  ('document database', 'A database that stores each record as a flexible, self-describing document, usually JSON, rather than as a row in a fixed table.'),
  ('key-value store', 'A very simple, very fast database that stores each item under a unique name (the key) and looks it up by that name.'),
  ('graph database', 'A database designed around things and the relationships between them, which makes questions about connections quick to answer.'),
  ('time-series database', 'A database built for values recorded over time, such as sensor readings, and for questions about trends.'),
  ('Microsoft Graph', 'Microsoft\'s API for the data in Microsoft 365: people, mail, calendars, Teams, files and more, all connected.'),
  ('YAML', 'A human-friendly format for configuration, written as indented lines of name: value, widely used to describe how systems should be set up.'),
  ('concurrency', 'Several things happening at the same time, such as many users using one system at once.'),
  ('race condition', 'A bug where the result depends on which of two simultaneous actions happens to finish first. It can work perfectly in testing and fail rarely in real use.'),
  ('transaction', 'A group of database steps treated as a single unit: either all of them succeed together or none of them take effect.'),
  ('ACID', 'Four guarantees that make database transactions trustworthy: Atomicity (all or nothing), Consistency (rules always hold), Isolation (users do not interfere) and Durability (once saved, it stays saved).'),
  ('rollback', 'Undoing every step of an unfinished transaction so the data is exactly as it was before it started.'),
  ('locking', 'Reserving a piece of data so that only one user or process can change it at a time while others wait.'),
  ('idempotency key', 'A unique label sent with a request so that if the same request is sent twice by mistake, the system recognises it and does the action only once.'),
  ('ledger', 'An append-only record of every change, such as a bank\'s list of every debit and credit, where nothing is overwritten and the current balance is worked out from the entries.'),
  ('eventual consistency', 'A design in which different parts of a system may briefly disagree after a change but are guaranteed to agree shortly afterwards.'),
  ('stored procedure', 'Business logic saved and run inside the database itself, rather than in the application.'),
  ('large language model', 'A kind of AI trained on vast amounts of text to predict and generate language. ChatGPT and Claude are built on large language models.'),
  ('prompt', 'The instructions and context you give an AI tool, which strongly shape what it produces.'),
  ('hallucination', 'When an AI tool states something fluently and confidently that is false or invented.');
